try {

const entrada = $input.first().json;
const esperado = $env.ADORBIT_N8N_WEBHOOK_TOKEN;
const recibido = (entrada.headers || {})['x-webhook-token'];
const fallo = (estado_http, codigo, mensaje) => [{ json: { ok: false, estado_http, respuesta: { codigo, mensaje } } }];
if (!esperado || recibido !== esperado) return fallo(401, 'no_autenticado', 'Falta o es invalido el encabezado X-Webhook-Token');
const b = entrada.body || {};

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const errores = {};
if (!uuidRe.test(b.cliente_id || '')) errores.cliente_id = 'UUID invalido';
if (typeof b.titulo !== 'string' || b.titulo.trim() === '' || b.titulo.length > 200) errores.titulo = 'Obligatorio, maximo 200 caracteres';
const inicio = new Date(b.inicio);
if (!b.inicio || Number.isNaN(inicio.getTime())) errores.inicio = 'Fecha-hora ISO-8601 invalida';
else if (inicio.getTime() < Date.now()) errores.inicio = 'Debe ser futura';
const duracion = Number(b.duracion_min ?? 60);
if (!Number.isInteger(duracion) || duracion < 15 || duracion > 480) errores.duracion_min = 'Entre 15 y 480 minutos';
if (b.notas !== undefined && String(b.notas).length > 2000) errores.notas = 'Maximo 2000 caracteres';
const desconocidos = Object.keys(b).filter((k) => !['cliente_id', 'titulo', 'inicio', 'duracion_min', 'notas'].includes(k));
if (desconocidos.length) errores.campos = 'No permitidos: ' + desconocidos.join(', ');
if (Object.keys(errores).length) return [{ json: { ok: false, estado_http: 400, respuesta: { codigo: 'solicitud_invalida', mensaje: 'Hay campos invalidos', detalle: errores } } }];
return [{ json: { ok: true, datos: { cliente_id: b.cliente_id, titulo: b.titulo.trim(), inicio: inicio.toISOString(), duracion_min: duracion, notas: b.notas ?? '' } } }];

} catch (e) {
  return [{ json: { ok: false, estado_http: 500, respuesta: { codigo: 'error_interno', mensaje: 'Fallo interno del flujo', detalle: String((e && e.message) || e) } } }];
}

try {

const esc = (t) => String(t ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const hoy = () => new Date().toLocaleDateString('en-CA', { timeZone: 'America/La_Paz' });
const sumarDias = (iso, d) => { const f = new Date(iso + 'T00:00:00Z'); f.setUTCDate(f.getUTCDate() + d); return f.toISOString().slice(0, 10); };
// Hash no criptografico (el entorno de Code de n8n no permite require('crypto')): solo para claves de idempotencia / UID.
const hash = (texto) => {
  const una = (s) => { let h1 = 0xdeadbeef, h2 = 0x41c6ce57; for (let i = 0; i < s.length; i++) { const c = s.charCodeAt(i); h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0'); };
  return una(texto) + una([...texto].reverse().join(''));
};
// Memoria entre ejecuciones del flujo. Se guarda como texto JSON: los objetos anidados de static data fallan en n8n 2.x.
const memoriaLeer = (nombre, porDefecto) => { try { const t = $getWorkflowStaticData('global')[nombre]; return t ? JSON.parse(t) : porDefecto; } catch (e) { return porDefecto; } };
const memoriaGuardar = (nombre, valor) => { $getWorkflowStaticData('global')[nombre] = JSON.stringify(valor); };
const destinatario = (cliente, patron) => {
  const conEmail = ((cliente && cliente.contactos) || []).filter((c) => c.email);
  return conEmail.find((c) => patron.test(c.rol || '')) || conEmail[0] || null;
};
const logoSvg = '<svg width="32" height="32" viewBox="0 0 128 128" fill="none" xmlns="http://www.w3.org/2000/svg" style="vertical-align:middle;display:inline-block;"><path d="M25 104 L57 25 Q59 20 65 20 L69 20 Q74 20 76 25 L108 104 L86 104 L65 48 L45 104 Z" fill="#4f46e5"/><path d="M103 37 C80 31 38 48 19 69 C-2 92 21 102 58 91 C80 85 100 74 111 62 L105 57 C91 70 72 79 54 84 C26 92 16 87 28 75 C44 58 80 43 100 44 Z" fill="#4f46e5"/><circle cx="110" cy="39" r="8" fill="#4f46e5"/></svg>';
const plantilla = (titulo, cuerpo) => `<div style="background-color:#f1f5f9;padding:28px 12px;margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased;">
<div style="max-width:580px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;box-shadow:0 10px 15px -3px rgba(0,0,0,0.07);">
  <div style="padding:20px 26px;background:#ffffff;border-bottom:1px solid #f1f5f9;">
    <table width="100%" cellpadding="0" cellspacing="0" border="0">
      <tr>
        <td style="vertical-align:middle;">
          ${logoSvg}
          <span style="font-size:21px;font-weight:800;color:#0f172a;letter-spacing:-0.5px;margin-left:8px;vertical-align:middle;">AdOrbit</span>
        </td>
        <td align="right" style="vertical-align:middle;">
          <span style="display:inline-block;background:#eef2ff;color:#4f46e5;font-size:11px;font-weight:700;padding:4px 10px;border-radius:20px;letter-spacing:0.5px;text-transform:uppercase;">Automatización</span>
        </td>
      </tr>
    </table>
  </div>
  <div style="height:3px;background:linear-gradient(90deg,#4f46e5 0%,#818cf8 100%);"></div>
  <div style="padding:28px 26px;color:#1e293b;font-size:14px;line-height:1.65;">
    <h2 style="font-size:19px;font-weight:700;color:#0f172a;margin:0 0 16px 0;letter-spacing:-0.3px;">${esc(titulo)}</h2>
    ${cuerpo}
  </div>
  <div style="background:#f8fafc;padding:18px 26px;border-top:1px solid #e2e8f0;text-align:center;font-size:12px;color:#64748b;">
    <p style="margin:0 0 4px 0;font-weight:600;color:#334155;">AdOrbit · Plataforma Publicitaria y Gestión Multicanal</p>
    <p style="margin:0;font-size:11px;color:#94a3b8;">Mensaje generado automáticamente · Por favor, no responda directamente a este correo.</p>
  </div>
</div>
</div>`;

const datos = $('Validar solicitud').first().json.datos;
const cliente = $input.first().json && $input.first().json.id ? $input.first().json : null;
if (!cliente) return [{ json: { ok: false, estado_http: 404, respuesta: { codigo: 'cliente_no_encontrado', mensaje: 'No existe el cliente' } } }];
const dest = destinatario(cliente, /direc|gerent|compras|marketing/i);
if (!dest) return [{ json: { ok: false, estado_http: 422, respuesta: { codigo: 'cliente_sin_contacto', mensaje: 'El cliente no tiene un contacto con correo' } } }];

const fin = new Date(new Date(datos.inicio).getTime() + datos.duracion_min * 60000);
const f = (d) => d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const texto = (t) => String(t).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
const uid = hash(datos.cliente_id + datos.inicio) + '@adorbit';
const remitente = (($env.ADORBIT_CORREO_REMITENTE.match(/<(.+)>/) || [])[1]) || $env.ADORBIT_CORREO_REMITENTE;
const ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//AdOrbit//n8n//ES', 'METHOD:REQUEST', 'BEGIN:VEVENT',
  `UID:${uid}`, `DTSTAMP:${f(new Date())}`, `DTSTART:${f(new Date(datos.inicio))}`, `DTEND:${f(fin)}`,
  `SUMMARY:${texto(datos.titulo)}`, `DESCRIPTION:${texto(datos.notas)}`,
  `ORGANIZER:mailto:${remitente}`, `ATTENDEE;CN=${texto(dest.nombre)}:mailto:${dest.email}`,
  'END:VEVENT', 'END:VCALENDAR'].join('\r\n') + '\r\n';
const cuando = new Date(datos.inicio).toLocaleString('es-BO', { timeZone: 'America/La_Paz', dateStyle: 'full', timeStyle: 'short' });
const cuerpo = `<p>Hola ${esc(dest.nombre)},</p><p>Le invitamos a la reunion <b>${esc(datos.titulo)}</b>.</p>
<p><b>Cuando:</b> ${esc(cuando)} (hora de Bolivia)<br><b>Duracion:</b> ${datos.duracion_min} minutos</p>
${datos.notas ? '<p>' + esc(datos.notas) + '</p>' : ''}<p>Adjuntamos la invitacion para su calendario.</p>`;
return [{
  json: { ok: true, para: dest.email, asunto: `Invitacion: ${datos.titulo}`, html: plantilla('Invitacion a reunion', cuerpo),
          respuesta: { estado: 'enviada', destinatario: dest.email, inicio: datos.inicio, duracion_min: datos.duracion_min, uid } },
  binary: { invitacion: { data: Buffer.from(ics, 'utf8').toString('base64'), mimeType: 'text/calendar', fileName: 'reunion.ics' } },
}];

} catch (e) {
  return [{ json: { ok: false, estado_http: 500, respuesta: { codigo: 'error_interno', mensaje: 'Fallo interno del flujo', detalle: String((e && e.message) || e) } } }];
}
